 1	method Reverse(a: array<int>)
 2		modifies a;
 3		ensures forall k :: 0 <= k < a.Length ==> a[k] == old(a[(a.Length-1) - k]);
 4	{
 5		var l := a.Length - 1;
 6		var i := 0;
 7		while (i < l-i)
 8			invariant 0 <= i <= (l+1)/2;
 9			invariant forall k :: 0 <= k < i || l-i < k <= l ==> a[k] == old(a[l-k]);
10			invariant forall k :: i <= k <= l-i ==> a[k] == old(a[k]);
11		{
12			a[i], a[l-i] := a[l-i], a[i];
13			i := i + 1;
14		}
15	}
